// 主档、即时备份与三个时间间隔恢复点；写入失败始终留下上一份可用记录。
export function recoveryPoints(storage,key,parse){const points=[];for(const suffix of ['.backup','.checkpoint1','.checkpoint2','.checkpoint3']){try{const raw=storage.getItem(key+suffix);if(raw){const state=parse(raw);points.push({key:key+suffix,time:state.time,level:state.level,raw});}}catch{}}return points;}
export function loadProgress(storage,key,oldKeys,parse){let damaged=false;for(const candidate of [key,key+'.backup',key+'.checkpoint1',key+'.checkpoint2',key+'.checkpoint3',...oldKeys]){try{const raw=storage.getItem(candidate);if(!raw)continue;return{state:parse(raw),recovered:candidate.startsWith(key+'.'),migrated:oldKeys.includes(candidate),source:candidate};}catch{damaged=true;}}return{state:null,damaged};}
export function storeProgress(storage,key,raw,parse){const incoming=parse(raw),previous=storage.getItem(key);if(previous===raw)return;if(previous){let valid=false;try{parse(previous);valid=true;}catch{}if(valid){storage.setItem(key+'.backup',previous);let checkpoint=null;try{checkpoint=parse(storage.getItem(key+'.checkpoint1'));}catch{}if(!checkpoint||incoming.time-checkpoint.time>=60||incoming.time<checkpoint.time){for(let n=3;n>=2;n--){const old=storage.getItem(key+'.checkpoint'+(n-1));if(old)storage.setItem(key+'.checkpoint'+n,old);}storage.setItem(key+'.checkpoint1',previous);}}}storage.setItem(key,raw);}
